import { type ReactNode, useEffect, useState } from "react";

import styles from "./Palette.module.css";

/** The Material 3 tones generated by scripts/generate-primitive-colors.mjs in @sys42/ui. */
export const TONES = [100, 99, 98, 95, 90, 80, 70, 60, 50, 40, 35, 30, 25, 20, 15, 10, 5, 0];

export const PALETTE_ROLES = [
  "primary",
  "secondary",
  "tertiary",
  "neutral",
  "danger",
  "warning",
  "success",
] as const;

type PaletteProps = {
  role: (typeof PALETTE_ROLES)[number];
};

function useResolvedValues(names: string[]) {
  const [values, setValues] = useState<Record<string, string>>({});
  useEffect(() => {
    const computed = getComputedStyle(document.documentElement);
    const next: Record<string, string> = {};
    for (const name of names) {
      next[name] = computed.getPropertyValue(name).trim();
    }
    setValues(next);
    // The names are derived from static props, a joined string is a stable key.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [names.join(",")]);
  return values;
}

/**
 * Shows the 18 tones of one native color palette (`--color-{role}-{tone}`).
 * The colors come from the primitive tokens loaded by the site, and the hex
 * values are resolved in the browser, so the swatches always match the
 * installed @sys42/ui.
 */
export default function Palette({ role }: PaletteProps): ReactNode {
  const names = TONES.map((tone) => `--color-${role}-${tone}`);
  const values = useResolvedValues(names);

  return (
    <div className={styles.palette}>
      <div className={styles.name}>
        <code>{role}</code>
      </div>
      <div className={styles.tones}>
        {TONES.map((tone) => {
          const name = `--color-${role}-${tone}`;
          return (
            <div
              key={tone}
              className={styles.tone}
              style={{
                background: `var(${name})`,
                color: tone >= 50 ? "var(--color-neutral-10)" : "var(--color-neutral-100)",
              }}
              title={`${name}: ${values[name] ?? ""}`}
            >
              <span className={styles.toneNumber}>{tone}</span>
              <span className={styles.toneValue}>{values[name]}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/** All seven palettes. */
export function Palettes(): ReactNode {
  return (
    <div className={styles.palettes}>
      {PALETTE_ROLES.map((role) => (
        <Palette key={role} role={role} />
      ))}
    </div>
  );
}
